    assert.strictEqual(ms('2 days'), 172800000);
  });
});
"}, "note": "Changing `days?` to `days` in the parse regex removes support for the singular unit 'day', so ms('1 day') now returns undefined instead of 86400000. The switch still handles 'day', showing this was an accidental regression, not an intended removal."}
```

